ENUMS = {'ld4_config.mode': {0: 'spp', 1: 'spp_ext', 2: 'epp17', 3: 'epp19', 4: 'ieee1284', 7: 'ieee1284_epp'}, 'pmc2.clk_src': {0: 'x1_24mhz', 2: 'x1_48mhz', 3: 'multiplier'}}
FIELD_ENUM = {'ld4_config.mode': 'ld4_config.mode', 'pmc2.clk_src': 'pmc2.clk_src'}
CONSTANTS = {'CFG_DATA_PORT': {'value': 47, 'count': 1, 'stride': 1}, 'CFG_INDEX_PORT': {'value': 46, 'count': 1, 'stride': 1}, 'GPIO_BASE': {'value': 4032, 'count': 1, 'stride': 1}, 'PM_BASE': {'value': 4040, 'count': 1, 'stride': 1}}
TESTS = [('sid', 192, {'chip_id': 6, 'revision': 0}), ('ld4_config', 242, {'tristate': 0, 'clk_en': 1, 'pnp_spp': 0, 'cfg_regs': 1, 'mode': 7})]


def decode(name, value):
    """Field name -> value for a register or word."""
    return {f: (value >> lo) & ((1 << (hi - lo + 1)) - 1) for f, (hi, lo) in FIELDS[name].items()}


def encode(name, **fields):
    v = 0
    for f, x in fields.items():
        hi, lo = FIELDS[name][f]
        if x >> (hi - lo + 1):
            raise ValueError('%s.%s: %d does not fit' % (name, f, x))
        v |= x << lo
    return v


def describe(name, value):
    """decode, with enum labels where the field has an enum."""
    out = {}
    for f, x in decode(name, value).items():
        e = ENUMS.get(FIELD_ENUM.get('%s.%s' % (name, f)))
        out[f] = e.get(x, x) if e else x
    return out


def selftest():
    for name, value, expect in TESTS:
        got = decode(name, value)
        for f, want in expect.items():
            assert got[f] == want, (name, hex(value), f, got[f], want)
    return len(TESTS)


if __name__ == '__main__':
    print('%s: %d vectors ok' % (UNIT, selftest()))
